CREATE TABLE IF NOT EXISTS gogfake_precos (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    jogo_id INT UNSIGNED NOT NULL,
    nome VARCHAR(160) NOT NULL,
    slug VARCHAR(180) NOT NULL UNIQUE,
    plataforma VARCHAR(80) NOT NULL DEFAULT 'PC',
    preco_original DECIMAL(10,2) NOT NULL,
    preco_atual DECIMAL(10,2) NOT NULL,
    desconto TINYINT UNSIGNED NOT NULL DEFAULT 0,
    imagem VARCHAR(500) NOT NULL,
    url VARCHAR(255) NOT NULL,
    loja VARCHAR(30) NOT NULL DEFAULT 'GOGFake',
    genero VARCHAR(80) NOT NULL,
    descricao TEXT NOT NULL,
    avaliacao DECIMAL(3,1) NOT NULL DEFAULT 8.0,
    destaque VARCHAR(30) NOT NULL DEFAULT 'popular',
    data_atualizacao TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_gogfake_jogo_id (jogo_id),
    INDEX idx_gogfake_genero (genero),
    INDEX idx_gogfake_preco (preco_atual)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

